1	// Payments helpers for tallyhouse-billing.
2	
3	export function discountAmount(amount, pct) {
4	  return Math.round((amount * pct) / 100);
5	}
6	
7	export function billingDays(start, end) {
8	  const out = [];
9	  for (let d = start; d <= end; d += 1) out.push(d);
10	  return out;
11	}
12	
13	export function discountFraction(pct) {
14	  if (pct > 100) throw new RangeError("percentage out of range");
15	  return pct / 100;
16	}
17	
18	export function averageInvoice(values) {
19	  if (values.length === 0) return 0;
20	  return values.reduce((a, b) => a + b, 0) / values.length;
21	}
