5	function row(table, code) {
6	  const found = TABLES[table][normalizeCode(code)];
7	  if (!found) throw new Error(`unknown ${table} code: ${code}`);
8	  return { ...found };
9	}
10	
11	export function currency(code) {
12	  return row("currencies", code);
13	}
14	
15	export function region(code) {
16	  return row("regions", code);
