test("isOverdue", () => {
  assert.equal(m.isOverdue(10, 10), false);
  assert.equal(m.isOverdue(10, 11), true);
  assert.equal(m.isOverdue(10, 9), false);
});

test("clampSeats", () => {
  assert.equal(m.clampSeats(5, 1, 10), 5);
  assert.equal(m.clampSeats(0, 1, 10), 1);
  assert.equal(m.clampSeats(15, 1, 10), 10);
});

test("graceSeconds", () => {
  assert.equal(m.graceSeconds(1), 60);
  assert.equal(m.graceSeconds(5), 300);
  assert.equal(m.graceSeconds(60), 3600);
});

test("topAccounts", () => {
  const accounts = [
    { id: 1, balance: 100 },
    { id: 2, balance: 500 },
    { id: 3, balance: 250 }
  ];
  const sorted = m.topAccounts(accounts);
  assert.equal(sorted[0].balance, 500);
  assert.equal(sorted[1].balance, 250);
  assert.equal(sorted[2].balance, 100);
});

